from pathlib import Path
root=Path(__file__).resolve().parent
checks=[]
def check(label,ok): checks.append((label,bool(ok)))
fac=(root/'src/facilities/facilities.service.ts').read_text()
facmod=(root/'src/facilities/facilities.module.ts').read_text()
notif=(root/'src/notifications/notifications.service.ts').read_text()
entity=(root/'src/notifications/notification.entity.ts').read_text()
migration=(root/'src/database/migrations/1732400000000-UpdateFacilityBookingSlotUniqueness.ts').read_text()
ctrl=(root/'src/notifications/notifications.controller.ts').read_text()
push=(root/'src/notifications/push/firebase-push.service.ts').read_text()
docs=(root/'docs/phase-v24-facility-booking-notifications.md').read_text()
check('facility booking request creates an owner notification', 'FACILITY_BOOKING_REQUESTED' in fac and 'result.facility.ownerUserId' in fac)
check('patient confirmation creates a dedicated notification', 'FACILITY_BOOKING_CONFIRMED' in fac and 'تم تأكيد حجزك' in fac)
check('patient rejection creates a dedicated notification', 'FACILITY_BOOKING_REJECTED' in fac and 'تم رفض طلب حجزك' in fac)
check('rejection reason is included in the patient message', 'result.booking.statusNote' in fac and 'السبب:' in fac)
check('notifications are persisted before push delivery', 'await this.repo.save(this.repo.create' in notif and 'this.push.send' in notif)
check('push delivery failure does not fail the booking operation', 'Could not persist an in-app notification' in notif and 'return null' in notif)
check('push respects user push preference', 'preference?.pushEnabled !== false' in notif)
check('push payload includes notification id and booking data', 'payload.notificationId = notification.id' in notif and 'bookingId' in fac)
check('invalid device tokens are deactivated', "In(invalidTokens)" in notif)
check('facility notification types are defined', all(x in entity for x in ['facility_booking_requested','facility_booking_confirmed','facility_booking_rejected','facility_booking_cancelled']))
check('patient cancellation notifies the facility owner', 'FACILITY_BOOKING_CANCELLED' in fac and 'result.facility.ownerUserId' in fac and 'تم إلغاء حجز' in fac)
check('released rejected or cancelled slots can be booked again', "status IN ('requested', 'confirmed')" in migration and 'DROP INDEX IF EXISTS uq_facility_booking_slot' in migration)
check('facility module imports notification module', 'NotificationsModule' in facmod)
check('patient can list and mark notifications using existing inbox endpoints', all(x in ctrl for x in ["@Get()", "@Patch(':id/read')", "@Get('unread-count')"]))
check('Firebase push remains optional when credentials are absent', 'FCM is not configured' in push and 'return { successCount: 0, failureCount: 0, disabled: !this.enabled }' in push)
check('request notification is dispatched after transaction result is created', fac.index('const result = await this.dataSource.transaction') < fac.index('userId: result.facility.ownerUserId'))
check('decision notification is dispatched after status transaction result is created', fac.index('const result = await this.dataSource.transaction', fac.index('async updateBookingStatus')) < fac.index('userId: result.booking.bookedByUserId'))
check('documentation describes notification events and setup', 'facility_booking_requested' in docs and 'FIREBASE_SERVICE_ACCOUNT_JSON' in docs)
for label,ok in checks: print(('PASS' if ok else 'FAIL')+' '+label)
print(f'{sum(ok for _,ok in checks)}/{len(checks)} checks passed')
raise SystemExit(0 if all(ok for _,ok in checks) else 1)
